from datetime import datetime, timedelta

class CalendarUtil:
    SLOT_DURATION_MINUTES = 60
    DAY_START_HOUR = 0
    DAY_START_MINUTE = 0
    DAY_END_HOUR = 23
    DAY_END_MINUTE = 59

    def __init__(self):
        self._events = []

    @property
    def events(self):
        return self._events.copy()

    def _set_events(self, events):
        self._events = list(events)

    def add_event(self, event):
        self._events.append(event)

    def remove_event(self, event):
        if event in self._events:
            self._events.remove(event)

    def _is_same_date(self, event_date, target_date):
        return event_date.date() == target_date.date()

    def get_events(self, date):
        events_on_date = []
        for event in self._events:
            if self._is_same_date(event['date'], date):
                events_on_date.append(event)
        return events_on_date

    def _is_time_overlap(self, start_time, end_time, event_start, event_end):
        return start_time < event_end and end_time > event_start

    def is_available(self, start_time, end_time):
        for event in self._events:
            if self._is_time_overlap(start_time, end_time, event['start_time'], event['end_time']):
                return False
        return True

    def _is_slot_available(self, slot_start_time):
        slot_end_time = slot_start_time + timedelta(minutes=self.SLOT_DURATION_MINUTES)
        return self.is_available(slot_start_time, slot_end_time)

    def _get_day_range(self, date):
        start_time = datetime(date.year, date.month, date.day, self.DAY_START_HOUR, self.DAY_START_MINUTE)
        end_time = datetime(date.year, date.month, date.day, self.DAY_END_HOUR, self.DAY_END_MINUTE)
        return start_time, end_time

    def get_available_slots(self, date):
        available_slots = []
        start_time, end_time = self._get_day_range(date)

        while start_time < end_time:
            if self._is_slot_available(start_time):
                slot_end_time = start_time + timedelta(minutes=self.SLOT_DURATION_MINUTES)
                available_slots.append((start_time, slot_end_time))
            start_time += timedelta(minutes=self.SLOT_DURATION_MINUTES)

        return available_slots

    def _is_upcoming(self, event_start_time, now):
        return event_start_time >= now

    def get_upcoming_events(self, num_events):
        now = datetime.now()
        upcoming_events = []
        for event in self._events:
            if self._is_upcoming(event['start_time'], now):
                upcoming_events.append(event)
            if len(upcoming_events) == num_events:
                break
        return upcoming_events
